UPDATE `filters` SET
	`description_uk` = '<h2>Чохли з футболістами для #model#</h2>
<p>Вибір гравця на чохлі — заява принциповіша, ніж здається. Мессі чи Роналду: суперечка, якій уже друге десятиліття, і кожен, хто дивиться футбол, має відповідь. Поруч із ними в добірці для #model# — Мбаппе, Холанд, Неймар і Ямаль, тобто ті, хто визначає гру просто зараз.</p>
<h3>Портрет, святкування чи момент матчу</h3>
<p>Портретні макети найчіткіші: обличчя велике, впізнається миттєво. Кадри святкування — емоційніші, з характерною позою, яку фанат зчитує з півпогляду. Динамічні моменти матчу виглядають найефектніше, але в них більше дрібних деталей, тому перед замовленням варто глянути прев&#39;ю саме під #model#: композиція будується навколо вирізу камери.</p>
<p>Клубні кольори теж мають значення. Один і той самий гравець у різній формі — це фактично різні чохли за настроєм, і фанати зазвичай точно знають, який період їм ближчий.</p>
<h3>Найпростіший подарунок фанату</h3>
<p>Якщо людина дивиться футбол, вгадати з гравцем неважко: улюбленця зазвичай називають у перших двох реченнях будь-якої розмови про матчі. Чохол на #model_uk# із його портретом — це подарунок, який точно буде щодня на очах, на відміну від чергового шарфа в шафі.</p>
<p>Хлопцям-підліткам ця тема заходить найкраще: постер на стіні вже не в моді, а телефон завжди з собою.</p>',
	`description_ru` = '<h2>Чехлы с футболистами для #model#</h2>
<p>Выбор игрока на чехле — заявление принципиальнее, чем кажется. Месси или Роналду: спор идёт уже второе десятилетие, и у каждого, кто смотрит футбол, есть ответ. Рядом с ними в подборке для #model# — Мбаппе, Холанд, Неймар и Ямаль, то есть те, кто определяет игру прямо сейчас.</p>
<h3>Портрет, празднование или момент матча</h3>
<p>Портретные макеты самые чёткие: лицо крупное, узнаётся мгновенно. Кадры празднования эмоциональнее, с характерной позой, которую фанат считывает с полувзгляда. Динамичные моменты матча выглядят эффектнее всего, но деталей в них больше, поэтому перед заказом стоит посмотреть превью именно под #model#: композиция строится вокруг выреза камеры.</p>
<p>Клубные цвета тоже важны. Один и тот же игрок в разной форме — фактически разные чехлы по настроению, и фанаты обычно точно знают, какой период им ближе.</p>
<h3>Самый простой подарок фанату</h3>
<p>Если человек смотрит футбол, с игроком не промахнуться: любимца называют в первых двух предложениях любого разговора о матчах. Чехол на #model_ru# с его портретом — подарок, который будет на глазах каждый день, в отличие от очередного шарфа в шкафу.</p>
<p>Мальчишкам-подросткам эта тема заходит лучше всего: постер на стене уже не в моде, а телефон всегда с собой.</p>',
	`updated_at` = NOW()
WHERE `site` = 'floy' AND `alias` = 'futbolisty' AND `parent_id` IS NULL;


-- -----------------------------------------------------------------------------
-- 1098 · futbolnye-kluby · Футбольні клуби / Футбольные клубы
--        (Real Madrid, PSG, Manchester United, інші)
--        кут: клуб — це надовше за гравця; кольори й емблема
-- -----------------------------------------------------------------------------
UPDATE `filters` SET
	`description_uk` = '<h2>Чохли футбольних клубів для #model#</h2>
<p>Гравці переходять з команди в команду, клуб лишається. Тому чохол з емблемою — вибір на довше, ніж чохол з портретом: через п&#39;ять років він означатиме рівно те саме, що й сьогодні.</p>
<p>У добірці для #model# є Real Madrid, PSG, Manchester United та інші відомі команди — здебільшого в двох варіантах подачі: чиста емблема на однотонному тлі й клубні кольори у вигляді смуг чи градієнта.</p>
<h3>Емблема чи кольори</h3>
<p>Герб — це прямо й однозначно: його впізнають навіть ті, хто футболом не цікавиться. Кольорові макети без великого логотипа працюють тонше: червоно-чорні або біло-сині смуги зчитує свій, а для решти це просто гарний графічний чохол. Другий варіант зручніший, якщо телефон часто на робочому столі.</p>
<p>Темні клубні кольори мають ще й практичну перевагу — на них менше видно щоденні сліди від пальців, ніж на білих макетах.</p>
<h3>Матчі, дербі та подарунки</h3>
<p>Такий чохол найчастіше купують до великих матчів або на день народження вболівальнику — коли шарф уже є, а футболка коштує в рази дорожче. Достатньо знати команду й точну назву телефона: #model_uk# і потрібна емблема — і подарунок готовий.</p>
<p>У родинах, де вболівають за різні клуби, це ще й привід для маленької війни на кухні. Зазвичай нешкідливої.</p>',
	`description_ru` = '<h2>Чехлы футбольных клубов для #model#</h2>
<p>Игроки переходят из команды в команду, клуб остаётся. Поэтому чехол с эмблемой — выбор на дольше, чем чехол с портретом: через пять лет он будет значить ровно то же, что и сегодня.</p>
<p>В подборке для #model# есть Real Madrid, PSG, Manchester United и другие известные команды — в основном в двух вариантах подачи: чистая эмблема на однотонном фоне и клубные цвета в виде полос или градиента.</p>
<h3>Эмблема или цвета</h3>
<p>Герб — прямо и однозначно: его узнают даже те, кто футболом не интересуется. Цветные макеты без крупного логотипа работают тоньше: красно-чёрные или бело-синие полосы считает свой, а для остальных это просто красивый графический чехол. Второй вариант удобнее, если телефон часто лежит на рабочем столе.</p>
<p>У тёмных клубных цветов есть и практичный плюс — на них меньше заметны ежедневные следы от пальцев, чем на белых макетах.</p>
<h3>Матчи, дерби и подарки</h3>
<p>Такой чехол чаще всего покупают к большим матчам или на день рождения болельщику — когда шарф уже есть, а футболка стоит в разы дороже. Достаточно знать команду и точное название телефона: #model_ru# и нужная эмблема — подарок готов.</p>
<p>В семьях, где болеют за разные клубы, это ещё и повод для маленькой войны на кухне. Обычно безобидной.</p>',
	`updated_at` = NOW()
WHERE `site` = 'floy' AND `alias` = 'futbolnye-kluby' AND `parent_id` IS NULL;


-- -----------------------------------------------------------------------------
-- 1127 · memi · Меми / Мемы  (Тралалело тралала та ін.)
--        кут: жарт із коротким терміном життя, який саме тому й працює
-- -----------------------------------------------------------------------------
UPDATE `filters` SET
	`description_uk` = '<h2>Чохли з мемами для #model#</h2>
<p>Мем на чохлі — це жарт, розказаний без слів. Хтось у черзі до каси побачить знайому картинку й засміється, і в цьому вся суть: тема живе рівно доти, доки жарт свіжий, і не претендує на більше.</p>
<p>Саме тому меми беруть інакше, ніж решту принтів. Тут ніхто не питає, чи буде це доречно через три роки — важливо, щоб зараз смішило. Тралалело тралала й інші герої інтернету для #model# — з цієї категорії речей.</p>
<h3>Чому це недорогий спосіб повеселитися</h3>
<p>Чохол — одна з небагатьох речей, які можна змінити на вихідних без жодних наслідків. Набрид жарт — поставили інший. Тому мем-принт часто стає другим чохлом «на настрій», поки основний лежить у шухляді.</p>
<p>Ще один сценарій — подарунок-жарт другу чи однокласнику. Це саме той випадок, коли головна цінність подарунка — реакція в момент відкриття, а не строк служби.</p>
<h3>Що врахувати</h3>
<p>Меми часто містять текст, а текст — найвразливіша частина будь-якого макета: його треба бачити повністю. Перегляньте прев&#39;ю під #model#, щоб переконатися, що напис не заходить у зону вирізу камери. І пам&#39;ятайте, що на #model_uk# картинку видно всім навколо — на роботі це іноді має значення.</p>',
	`description_ru` = '<h2>Чехлы с мемами для #model#</h2>
<p>Мем на чехле — это шутка, рассказанная без слов. Кто-то в очереди на кассе увидит знакомую картинку и засмеётся, и в этом весь смысл: тема живёт ровно столько, сколько свежа шутка, и на большее не претендует.</p>
<p>Поэтому мемы берут иначе, чем остальные принты. Здесь никто не спрашивает, будет ли это уместно через три года — важно, чтобы смешило сейчас. Тралалело тралала и другие герои интернета для #model# — как раз из этой категории вещей.</p>
<h3>Почему это недорогой способ повеселиться</h3>
<p>Чехол — одна из немногих вещей, которые можно поменять на выходных без последствий. Надоела шутка — поставили другую. Поэтому мем-принт часто становится вторым чехлом «под настроение», пока основной лежит в ящике.</p>
<p>Ещё сценарий — подарок-шутка другу или однокласснику. Тот самый случай, когда главная ценность подарка — реакция в момент открытия, а не срок службы.</p>
<h3>Что учесть</h3>
<p>В мемах часто есть текст, а текст — самая уязвимая часть любого макета: его нужно видеть целиком. Посмотрите превью под #model#, чтобы надпись не заходила в зону выреза камеры. И помните, что на #model_ru# картинку видят все вокруг — на работе это иногда имеет значение.</p>',
	`updated_at` = NOW()
WHERE `site` = 'floy' AND `alias` = 'memi' AND `parent_id` IS NULL;


-- =============================================================================
--  ПЕРЕВІРКА ПІСЛЯ ВИКОНАННЯ
-- =============================================================================
--  Має повернути 15 рядків, усі з непорожніми довжинами і has_model = 1:
--
--  SELECT `id`, `alias`, `title_uk`,
--         CHAR_LENGTH(`description_uk`) AS len_uk,
--         CHAR_LENGTH(`description_ru`) AS len_ru,
--         (`description_uk` LIKE '%#model#%' AND `description_ru` LIKE '%#model#%') AS has_model
--  FROM `filters`
--  WHERE `site` = 'floy' AND `type` = 'theme' AND `parent_id` IS NULL
--  ORDER BY `alias`;
--
--  Теми без статті (мають лишитись лише підтеми — у них свій текст не пишемо):
--
--  SELECT `alias`, `title_uk` FROM `filters`
--  WHERE `site` = 'floy' AND `type` = 'theme' AND `parent_id` IS NULL
--    AND (`description_uk` IS NULL OR `description_uk` = '');
--
--  Відкат (якщо робився бекап з кроку 0):
--
--  UPDATE `filters` f
--    JOIN `filters_desc_bak_20260804` b ON b.`id` = f.`id`
--     SET f.`description_uk` = b.`description_uk`,
--         f.`description_ru` = b.`description_ru`;
-- =============================================================================
